'use strict';

const fs = require('fs');
const path = require('path');

const ROOT = __dirname;
const README_PATH = path.join(ROOT, 'README.md');
const OUTPUT_DIR = path.join(ROOT, 'results');
const OUTPUT_FILE = path.join(OUTPUT_DIR, 'status.json');
const REQUEST_TIMEOUT_MS = 10000;
const EXPECTED_STATUS = 200;

function readEndpoint() {
  const fromEnv = (process.env.STATUS_ENDPOINT || process.env.STATUS_URL || '').trim();
  if (fromEnv) return fromEnv;

  const readme = fs.readFileSync(README_PATH, 'utf8');
  const match = readme.match(/https?:\/\/[^\s)'"<>]+/);
  if (!match) throw new Error(`No endpoint URL found in ${README_PATH}`);

  return match[0];
}

async function fetchStatus(endpoint) {
  const response = await fetch(endpoint, { signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS) });
  const body = (await response.text()).trim();

  if (!response.ok) {
    throw new Error(`GET ${endpoint} responded with HTTP ${response.status}`);
  }

  let payload = null;
  try {
    payload = JSON.parse(body);
  } catch {
    throw new Error(`GET ${endpoint} returned a non-JSON body: ${body}`);
  }

  const status = payload && typeof payload.status === 'number' ? payload.status : response.status;
  if (status !== EXPECTED_STATUS) {
    throw new Error(`GET ${endpoint} reported status=${status}, expected status=${EXPECTED_STATUS}`);
  }

  return { httpStatus: response.status, status };
}

async function main() {
  const endpoint = readEndpoint();
  const { httpStatus, status } = await fetchStatus(endpoint);

  fs.mkdirSync(OUTPUT_DIR, { recursive: true });
  fs.writeFileSync(OUTPUT_FILE, `${JSON.stringify({ status }, null, 2)}\n`);

  console.log(`GET ${endpoint} -> HTTP ${httpStatus}`);
  console.log(`Wrote ${path.relative(ROOT, OUTPUT_FILE)} -> status=${status}`);
}

main().catch((error) => {
  console.error(`client.js failed: ${error.message}`);
  process.exitCode = 1;
});

