'use strict';

const fs = require('fs');
const path = require('path');

const ROOT = __dirname;
const README_PATH = path.join(ROOT, 'README.md');
const OUTPUT_FILE = path.join(ROOT, 'results', 'status.json');
const REQUEST_TIMEOUT_MS = 10000;
const EXPECTED_STATUS = 200;

const checks = [];

function check(name, fn) {
  checks.push({ name, fn });
}

function readEndpoint() {
  const readme = fs.readFileSync(README_PATH, 'utf8');
  const urls = readme.match(/https?:\/\/[^\s)'"<>]+/g) || [];
  const statusUrl = urls.find((url) => url.includes('/status'));
  return statusUrl || urls[0] || null;
}

check('results/status.json exists', () => {
  if (!fs.existsSync(OUTPUT_FILE)) throw new Error(`${OUTPUT_FILE} is missing`);
});

check('results/status.json contains status=200', () => {
  const raw = fs.readFileSync(OUTPUT_FILE, 'utf8');
  const data = JSON.parse(raw);
  if (data.status !== EXPECTED_STATUS) {
    throw new Error(`expected status=${EXPECTED_STATUS}, got ${JSON.stringify(data.status)}`);
  }
});

check('client.js is implemented (no TODO placeholder)', () => {
  const source = fs.readFileSync(path.join(ROOT, 'client.js'), 'utf8');
  if (/TODO/.test(source)) throw new Error('client.js still contains a TODO placeholder');
});

check('endpoint from README responds with status=200', async () => {
  const endpoint = readEndpoint();
  if (!endpoint) throw new Error('No endpoint URL found in README.md');

  const response = await fetch(endpoint, { signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS) });
  if (response.status !== EXPECTED_STATUS) {
    throw new Error(`GET ${endpoint} responded with HTTP ${response.status}`);
  }

  const payload = JSON.parse((await response.text()).trim());
  if (payload.status !== EXPECTED_STATUS) {
    throw new Error(`GET ${endpoint} reported status=${JSON.stringify(payload.status)}`);
  }
});

(async () => {
  let failed = 0;

  for (const { name, fn } of checks) {
    try {
      await fn();
      console.log(`PASS  ${name}`);
    } catch (error) {
      failed += 1;
      console.error(`FAIL  ${name}: ${error.message}`);
    }
  }

  const total = checks.length;
  if (failed === 0) {
    console.log(`\nAll ${total} checks passed.`);
  } else {
    console.error(`\n${failed} of ${total} checks failed.`);
    process.exitCode = 1;
  }
})();

